import pprint
import functools
import logging


class SchemaInconsistent(Exception):
    pass


class SchemaField(object):
    def __init__(self, name, not_null=False, optional=False, klass=None, many=False, nested_klass=None):
        """
        Single field of Schema ORM, based on this type the SchemaObject is transferring data to and from the object.

        :param str name: String name of the field in Schema
        :param bool not_null: If set to True, value of this parameter cannot be None or empty string.
        :param bool optional: If set to True, parameter does not have to be present in
                                the schema dict or in schema parameters, it will have default constructor value.
        :param Type[SchemaObject] klass: If set, the data that is identified by `name` will be deserialized using class = klass
        :param (SchemaObject|SchemaObjects) nested_klass: class to be used for deserialization of nested dict value,
        e.g. for name="result"
        {
          "result": {
            "MRBTS-1234/NRBTS-1234": nested_klass
          }
        }
        """
        self.name = name
        self.not_null = not_null
        self.optional = optional
        self.klass = klass
        self.many = many
        self.nested_klass = nested_klass


class SchemaObject(object):
    def __init__(self):
        """
        Simple ORM to convert data structures from APIs into Object and to serialize Objects.
        This is used to check the minimal contract, and to control data presentation.
        """
        self.__check_not_null()

    def __check_not_null(self):
        for attribute_name, attribute_field in self.__get_schema_class_attributes():
            if attribute_field.not_null is True:
                attribute_value = getattr(self, attribute_name)
                if attribute_value is None or attribute_value == "":
                    error_msg = "{class_name} object attribute {attribute_name} is not allowed to be empty, but its provided value is empty."
                    raise ValueError(error_msg.format(
                        class_name=self.__class__.__name__,
                        attribute_name=attribute_name,
                    ))

    @classmethod
    def __get_schema_class_attributes(cls):
        for attribute_name in dir(cls):
            attribute_field = getattr(cls, attribute_name)

            if not isinstance(attribute_field, SchemaField):
                continue

            yield attribute_name, attribute_field

    @classmethod
    def __get_nested_objects(cls):
        for attribute_name in dir(cls):
            attribute_field = getattr(cls, attribute_name)

            if not isinstance(attribute_field, SchemaObject):
                continue

            yield attribute_name, attribute_field

    @classmethod
    def __rgetattr(cls, obj, attr):
        def _getattr(obj, attr):
            subscriptable = hasattr(obj, '__getitem__')
            if subscriptable:
                return obj.get(attr, None)
            return getattr(obj, attr, None)

        return functools.reduce(_getattr, [obj] + attr.split('.'))

    @classmethod
    def __map_data_to_object_or_object_list(cls, data, attribute_field):
        if data and attribute_field.many is True:
            return list(map(attribute_field.klass.from_object_dict, data))
        return attribute_field.klass.from_object_dict(data)

    @classmethod
    def __map_data_to_nested_object(cls, data, attribute_field):
        return {item[0]: attribute_field.nested_klass.from_object_dict(item[1])
                for item in data.items()}

    @classmethod
    def __map_data(cls, data, attribute_field):
        if data and attribute_field.klass:
            return cls.__map_data_to_object_or_object_list(data, attribute_field)
        elif data and attribute_field.nested_klass:
            return cls.__map_data_to_nested_object(data, attribute_field)
        else:
            return data

    @classmethod
    def __map_data_to_object_attributes(cls, data):

        object_attributes = dict()
        for attribute_name, attribute_field in cls.__get_schema_class_attributes():
            # noinspection PyBroadException
            try:
                extracted_value = cls.__rgetattr(data, attribute_field.name)
            except Exception:
                if attribute_field.optional:
                    continue
                raise

            object_attributes[attribute_name] = cls.__map_data(extracted_value, attribute_field)

        return object_attributes

    @classmethod
    def update_client_field(cls, obj, field_name, value):
        if hasattr(obj, field_name):
            setattr(obj, field_name, value)
            return
        if hasattr(obj, '_' + field_name):
            setattr(obj, '_' + field_name, value)
            return
        for attr, attr_value in vars(obj).items():
            if attr.startswith('_') and hasattr(attr_value, '__dict__'):
                return cls.update_client_field(attr_value, field_name, value)
        error_msg = '{} schema has no attribute {}'
        raise KeyError(error_msg.format(obj.__class__.__name__, field_name))

    def update_field(self, field_name, value):
        """
        Recursively search and modify SchemaObject field

        :param field_name: name of field to change
        :param value: new field value

        :raises: KeyError: if object has no attribute with `field_name` name
        :return: None
        """
        if hasattr(self, field_name):
            setattr(self, field_name, value)
            return
        else:
            for attribute in dir(self):
                attribute_field = getattr(self, attribute)
                if isinstance(attribute_field, SchemaObject):
                    return attribute_field.update_field(field_name, value)
        error_msg = '{} schema has no attribute {}'
        raise KeyError(error_msg.format(self.__class__.__name__, field_name))

    @classmethod
    def from_object_dict(cls, data):
        """
        Load data from dictionary structure into the object.

        :param dict data: Data of given schema
        :return SchemaObject: Returns instance of subclass of SchemaObject.
        """
        try:
            return cls(**cls.__map_data_to_object_attributes(data))
        except (KeyError, AttributeError, ValueError) as e:
            error_msg = "\nSchema data is inconsistent or faulty.\nError on {}"
            raw_output = "RAW output from internal client:\n{}" + error_msg
            logging.basicConfig(format='%(asctime)s %(message)s')
            logging.error(raw_output.format(data, e))
            raise SchemaInconsistent(error_msg.format(e))

    def __deserialize(self, model_field, attribute_value):
        if attribute_value and model_field.klass:
            return attribute_value.to_dict() if not model_field.many else [
                item.to_dict()
                for item in
                attribute_value]
        elif attribute_value and model_field.nested_klass:
            return {item[0]: item[1].to_dict()
                    for item in attribute_value.items()}
        else:
            return attribute_value

    def to_dict(self):
        """
        Serialize to dictionary structure.

        :return dict: Object as dict, with schema data parameters.
        """
        dict_data = dict()

        try:
            for attribute_name in dir(self):

                object_type = type(self)
                model_field = getattr(object_type, attribute_name)
                if not isinstance(model_field, SchemaField) or attribute_name.startswith("_"):
                    continue
                attribute_value = getattr(self, attribute_name)
                parameter_name = attribute_name
                if not attribute_value and model_field.optional:
                    continue
                dict_data[parameter_name] = self.__deserialize(model_field, attribute_value)

        except AttributeError as e:
            error_msg = "Schema attributes that is being serialized is not consistent. Error on {}"
            raise SchemaInconsistent(error_msg.format(e))

        return dict_data

    def to_object(self, klass):
        """
        Serialize back to taf.internal.nms.nom.client data structures

        Usage example:
        >>> from taf.nms.nom.schemas.operations.operation_status import OperationStatusResponse
        >>> from nokia_nom_open_api_client import OperationHistoryStatusResponseStruct
        >>>
        >>> current_obj = OperationStatusResponse(operation_id='111', timestamp='222', status='333')
        >>> api_obj = current_obj.to_object(OperationHistoryStatusResponseStruct)

        >>> from taf.nms.nom.schemas.operations.operation_schedule import (OperationScheduledResponse,
        >>>                                                                OperationScheduleTypeResponse)
        >>> from nokia_nom_open_api_client import ScheduledOperation, ScheduleType
        >>>
        >>> current_obj = OperationScheduledResponse(
        >>>     schedule_id='123',
        >>>     schedule=OperationScheduleTypeResponse(
        >>>         date_time='123',
        >>>         ...)
        >>>     ...)
        >>> api_obj = current_obj.to_object( (ScheduledOperation, {'schedule': ScheduleType}) )

        :param klass: Union[Type, tuple]: class that current object will be serialized to
                                          use class Type if current object is 'flat' (only attributes with simple types)
                                          use structure with nested tuples if object has underlay data structures
        :return: object: Serialized data scheme from taf.internal.nms.nom.client
        """
        arguments = dict()
        if isinstance(klass, tuple):
            if len(klass) != 2:
                error_msg = "Illegal number of tuple elements. " \
                            "Only tuples like `(class_name, nested_classes_dict)` are allowed."
                raise AttributeError(error_msg)
            klass, nested_klasses_dict = klass
            for attribute_name, nested_klass in nested_klasses_dict.items():
                arguments[attribute_name] = getattr(self, attribute_name).to_object(nested_klass)
        arguments.update({var: value for var, value in vars(self).items() if var not in arguments})
        return klass(**arguments)

    def __repr__(self):
        """For `print` and `pprint`"""
        return pprint.pformat(self.to_dict())

    def __eq__(self, other):
        """Returns true if both objects are equal"""
        if not isinstance(other, self.__class__):
            return False

        return self.to_dict() == other.to_dict()


class SchemaObjects(list):
    """
    Extend SchemaObject to support multiple SchemaObject provided as items of list.
    """
    schema = None

    @classmethod
    def from_object_dict(cls, data):
        """
        :param list(dict) data: List of data of given schema.
        :return list(SchemaObject): Returns list of instance of subclass of SchemaObject.
        """
        return cls(list(map(lambda r: cls.schema.from_object_dict(r), data)))

    def to_dict(self):
        """
        :return list(dict): list of objects converted to dicts, with schema data parameters.
        """
        return list(map(lambda r: r.to_dict(), self))

    def __eq__(self, other):
        """Returns true if both objects are equal"""
        if not isinstance(other, self.__class__):
            return False

        return self.to_dict() == other.to_dict()
